package com.johnny.hotel.invoice;import com.johnny.hotel.exception.BusinessException;import lombok.RequiredArgsConstructor;import org.springframework.stereotype.Service;import java.util.*;
@Service @RequiredArgsConstructor public class FinanceReadService{private final FinanceReadMapper mapper;private final InvoiceAccess access;public List<Map<String,Object>> read(String domain,Integer page,Integer size){access.finance(access.actor());int p=page==null?1:page,s=size==null?50:size;if(p<1||s<1||s>100)throw new BusinessException("Invalid pagination");int o=(p-1)*s;return switch(domain){case "bookings"->mapper.bookings(o,s);case "assignments"->mapper.assignments(o,s);case "rooms"->mapper.rooms(o,s);case "stays"->mapper.stays(o,s);case "guests"->mapper.guests(o,s);case "cleaning"->mapper.cleaning(o,s);case "inspections"->mapper.inspections(o,s);case "work-orders"->mapper.workOrders(o,s);case "turnovers"->mapper.turnovers(o,s);default->throw new BusinessException(404,"Finance record domain not found");};}}
